import type { ToolItem } from './schemas';

const PUBLISHED_ON = '2026-11-16';
type ToolSpec = Omit<ToolItem, 'id' | 'status' | 'section' | 'kind' | 'featured' | 'publishedAt' | 'updatedAt'> & { featured?: boolean };

function makeTool(spec: ToolSpec): ToolItem {
  return {
    ...spec,
    id: `tool-${spec.slug}`,
    status: 'published',
    section: 'tools',
    kind: 'tool',
    featured: spec.featured ?? false,
    publishedAt: PUBLISHED_ON,
    updatedAt: PUBLISHED_ON,
  };
}

